"""Apply inbound static ``set:`` button taps before the orchestrator runs."""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Callable, Iterable, Mapping, NamedTuple

import structlog

from rasa.mantle.content.responses import (
    BUTTON_PAYLOAD_KEY,
    VARIANT_BUTTONS_KEY,
)
from rasa.mantle.content.static_buttons import (
    InboundButtonPayloadKind,
    ParsedStaticSetMemoryPayload,
    active_skill_can_write_set_memory,
    classify_inbound_button_payload,
    coerce_set_memory_button_value,
    is_set_memory_payload,
)
from rasa.mantle.memory.field import MemoryField
from rasa.mantle.memory.manager import PROJECT_NAMESPACE
from rasa.mantle.memory.schema import ProjectMemorySchema
from rasa.mantle.orchestration.settable_write import write_settable_field
from rasa.mantle.skills.catalog import SkillCatalog
from rasa.mantle.state.turn import IncomingTurn
from rasa.shared.core.events import BotUttered, Event

if TYPE_CHECKING:
    from rasa.mantle.orchestration.settable_write import CallToolFunc
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()

# Packaged in ``default_skills/default_responses.yml``; builders may override.
UTTER_SET_MEMORY_BUTTON_SKIPPED = "utter_set_memory_button_skipped"
# Channel metadata key and matching placeholder in the packaged skip notice.
BUTTON_TITLE_METADATA_KEY = "button_title"
BUTTON_TITLE_PLACEHOLDER = f"{{{BUTTON_TITLE_METADATA_KEY}}}"
SET_MEMORY_BUTTON_WRITE_SKIPPED_EVENT = "mantle.set_memory_button.write_skipped"


def prompt_text_for_set_memory_utterance(
    text: str, metadata: Mapping[str, Any]
) -> str | None:
    """Return prompt text for a user line, hiding a raw ``set:`` payload.

    Plain text is unchanged. A ``set:`` line becomes the sanitized button
    title, or ``None`` when the channel sent no title so the payload is omitted.
    """
    if not is_set_memory_payload(text):
        return text
    return button_title_from_metadata(metadata)


def button_title_from_metadata(metadata: Mapping[str, Any]) -> str | None:
    """Return the button title from channel metadata when the channel supplies it.

    Curly braces are stripped so a client-supplied title cannot inject
    ``{session…}`` or ``{entry}`` tokens into a later
    :func:`~rasa.mantle.orchestration.memory_utils.substitute_memory_placeholders`
    pass (for example a REST body with
    ``metadata.button_title: "{session.order.credit_card}"``).
    """
    raw_title = metadata.get(BUTTON_TITLE_METADATA_KEY)
    if not isinstance(raw_title, str):
        return None
    sanitized = raw_title.replace("{", "").replace("}", "").strip()
    return sanitized or None


def fill_set_memory_button_skip_notice(
    template: str, metadata: Mapping[str, Any]
) -> str:
    """Insert ``button_title`` into the skip-button notice template.

    Call this **before** memory placeholder substitution so a real memory
    entry named ``button_title`` cannot override the channel title.

    Channels that forward ``button_title`` get
    ``That selection 'Gold' is no longer available or an invalid value…``.
    When the title is missing, the quoted ``{button_title}`` token is removed
    so the line stays grammatical. The inserted title is untrusted channel
    input; the packaged skip utterance does not rephrase, so the title is not
    sent to an LLM. Callers must still keep the raw ``set:`` payload out of any
    prompt that does run.
    """
    title = button_title_from_metadata(metadata)
    if title is not None:
        return template.replace(BUTTON_TITLE_PLACEHOLDER, title)
    return (
        template.replace(f" '{BUTTON_TITLE_PLACEHOLDER}'", "")
        .replace(f"'{BUTTON_TITLE_PLACEHOLDER}'", "")
        .replace(BUTTON_TITLE_PLACEHOLDER, "")
    )


def latest_bot_message_button_payloads(events: Iterable[Event]) -> frozenset[str]:
    """Return button payloads from the most recent ``BotUttered``, if any.

    Only the latest agent message counts. Older offers and messages without
    buttons yield an empty set so forged ``set:`` channel text cannot write
    memory.
    """
    latest_bot: BotUttered | None = None
    for event in events:
        if isinstance(event, BotUttered):
            latest_bot = event
    if latest_bot is None:
        return frozenset()

    raw_buttons = latest_bot.data.get(VARIANT_BUTTONS_KEY) if latest_bot.data else None
    if not isinstance(raw_buttons, list):
        return frozenset()

    payloads: set[str] = set()
    for button in raw_buttons:
        if not isinstance(button, Mapping):
            continue
        payload = button.get(BUTTON_PAYLOAD_KEY)
        if isinstance(payload, str) and payload:
            payloads.add(payload)
    return frozenset(payloads)


def inbound_set_payload_was_offered(payload: str, events: Iterable[Event]) -> bool:
    """Return whether *payload* appears on the latest agent message's buttons."""
    return payload in latest_bot_message_button_payloads(events)


def _button_write_targets(memory_key: str) -> tuple[str, str | None]:
    """Return the bare entry name and optional project slot for a button write.

    Skill-scoped payloads use bare-name resolution via :meth:`MemoryManager.set`.
    Project payloads pass an explicit ``project.{entry}`` slot so the payload
    namespace is authoritative (button intercept only).
    """
    owner_id, entry_name = memory_key.split(".", 1)
    project_slot = memory_key if owner_id == PROJECT_NAMESPACE else None
    return entry_name, project_slot


def _memory_field_for_set_payload(
    parsed: ParsedStaticSetMemoryPayload,
    *,
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> MemoryField | None:
    """Return the declared field for a parsed ``set:`` payload, if any."""
    owner_id, entry_name = parsed.memory_key.split(".", 1)
    if owner_id == PROJECT_NAMESPACE:
        return project_memory.fields.get(entry_name)
    skill = skill_catalog.skill_by_id(owner_id)
    if skill is None:
        return None
    return skill.memory.definition.all_fields().get(entry_name)


def _skip_set_memory_button_turn(turn: IncomingTurn) -> IncomingTurn:
    """Return a turn that ends with the packaged unusable-button notice."""
    return turn.model_copy(
        update={
            "suppress_llm_user_message": True,
            "skip_set_memory_button_tap": True,
        }
    )


def _skip_unwritable_tap(
    turn: IncomingTurn,
    *,
    active_skill_id: str | None,
    memory_key: str,
    reason: str,
) -> IncomingTurn:
    """Log a skip and return a stale-notice turn."""
    structlogger.info(
        SET_MEMORY_BUTTON_WRITE_SKIPPED_EVENT,
        active_skill_id=active_skill_id,
        memory_key=memory_key,
        reason=reason,
    )
    return _skip_set_memory_button_turn(turn)


def _turn_for_invalid_set_memory(turn: IncomingTurn) -> IncomingTurn:
    """Handle a malformed ``set:`` payload that did not parse."""
    title = button_title_from_metadata(turn.metadata)
    if title is None:
        structlogger.warning(
            "mantle.set_memory_button.invalid_payload",
            event_info=(
                "Malformed set-memory button payload with no button_title "
                "metadata; notifying the user and ending the turn without "
                "the LLM."
            ),
        )
        return _skip_set_memory_button_turn(turn)
    structlogger.warning(
        "mantle.set_memory_button.invalid_payload",
        event_info=(
            "Malformed set-memory button payload; sending the button title "
            "to the LLM for interpretation instead of the raw payload."
        ),
    )
    return turn.model_copy(
        update={
            "suppress_llm_user_message": True,
            "llm_user_message": title,
        }
    )


class _ButtonWritePlan(NamedTuple):
    """Validated write targets for an offered ``set:`` tap."""

    skill_id: str
    flow_id: str
    entry_name: str
    button_project_slot_name: str | None
    coerced_value: Any
    active_skill_id: str | None


def _plan_set_memory_button_write(
    turn: IncomingTurn,
    parsed: ParsedStaticSetMemoryPayload,
    *,
    tracker_handle: "TrackerHandle",
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> _ButtonWritePlan | IncomingTurn:
    """Return a write plan, or a stale-notice turn when the tap must not write."""
    if not inbound_set_payload_was_offered(turn.text, tracker_handle.tracker.events):
        return _skip_unwritable_tap(
            turn,
            active_skill_id=tracker_handle.active_skill_id,
            memory_key=parsed.memory_key,
            reason="payload_not_on_latest_bot_message",
        )

    active_skill_id = tracker_handle.active_skill_id
    if not active_skill_can_write_set_memory(
        parsed,
        active_skill_id=active_skill_id,
        skill_catalog=skill_catalog,
        project_memory=project_memory,
    ):
        return _skip_unwritable_tap(
            turn,
            active_skill_id=active_skill_id,
            memory_key=parsed.memory_key,
            reason="not_writable_for_active_skill",
        )

    skill_id, flow_id = tracker_handle.memory_scope()
    if not skill_id:
        return _skip_unwritable_tap(
            turn,
            active_skill_id=active_skill_id,
            memory_key=parsed.memory_key,
            reason="no_active_scope",
        )

    field = _memory_field_for_set_payload(
        parsed, skill_catalog=skill_catalog, project_memory=project_memory
    )
    if field is None:
        return _skip_unwritable_tap(
            turn,
            active_skill_id=active_skill_id,
            memory_key=parsed.memory_key,
            reason="missing_field",
        )

    coerced_value = coerce_set_memory_button_value(parsed.value, field)
    if coerced_value is None:
        return _skip_unwritable_tap(
            turn,
            active_skill_id=active_skill_id,
            memory_key=parsed.memory_key,
            reason="invalid_value",
        )

    entry_name, button_project_slot_name = _button_write_targets(parsed.memory_key)
    return _ButtonWritePlan(
        skill_id=skill_id,
        flow_id=flow_id,
        entry_name=entry_name,
        button_project_slot_name=button_project_slot_name,
        coerced_value=coerced_value,
        active_skill_id=active_skill_id,
    )


def _turn_after_memory_validation_reject(
    turn: IncomingTurn,
    suppressed_turn: IncomingTurn,
    *,
    active_skill_id: str | None,
    memory_key: str,
) -> IncomingTurn:
    """Suppress the payload after a rejecting memory validation tool; keep the title."""
    structlogger.error(
        "mantle.set_memory_button.write_failed",
        active_skill_id=active_skill_id,
        memory_key=memory_key,
        memory_validation_failed=True,
    )
    title = button_title_from_metadata(turn.metadata)
    if title is None:
        return suppressed_turn
    return suppressed_turn.model_copy(update={"llm_user_message": title})


async def _dispatch_set_memory_button_write(
    turn: IncomingTurn,
    parsed: ParsedStaticSetMemoryPayload,
    plan: _ButtonWritePlan,
    *,
    tracker_handle: "TrackerHandle",
    tool_funcs: Mapping[str, Mapping[str, Callable]],
    call_tool_func: "CallToolFunc",
) -> IncomingTurn:
    """Write the planned field and map the outcome to an inbound turn."""
    suppressed_turn = turn.model_copy(update={"suppress_llm_user_message": True})
    write_result = await write_settable_field(
        tracker_handle,
        plan.skill_id,
        plan.flow_id,
        plan.entry_name,
        plan.coerced_value,
        tool_funcs,
        call_tool_func,
        button_project_slot_name=plan.button_project_slot_name,
    )
    if write_result.ok:
        structlogger.info(
            "mantle.set_memory_button.written",
            active_skill_id=plan.active_skill_id,
            memory_key=parsed.memory_key,
        )
        return suppressed_turn.model_copy(
            update={
                "llm_user_message": button_title_from_metadata(turn.metadata),
                "set_memory_button_written_key": parsed.memory_key,
            }
        )
    if write_result.memory_validation_failed:
        return _turn_after_memory_validation_reject(
            turn,
            suppressed_turn,
            active_skill_id=plan.active_skill_id,
            memory_key=parsed.memory_key,
        )
    return _skip_unwritable_tap(
        turn,
        active_skill_id=plan.active_skill_id,
        memory_key=parsed.memory_key,
        reason="memory_write_denied",
    )


async def apply_inbound_set_memory_button_tap(
    *,
    tracker_handle: "TrackerHandle",
    turn: IncomingTurn,
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    tool_funcs: Mapping[str, Mapping[str, Callable]],
    call_tool_func: "CallToolFunc",
) -> IncomingTurn:
    """Intercept a static ``set:`` button tap and write memory when allowed.

    Returns *turn* unchanged for plain text. Valid ``set:`` taps that are written
    or skipped suppress the raw payload from the LLM prompt. A write that is
    kept sets ``llm_user_message`` to the sanitized button label when the
    channel sent one, and ``set_memory_button_written_key`` so the prompt can
    say that field is already stored. Invalid ``set:`` shapes use
    ``button_title`` metadata when present so the LLM can interpret the tap
    like typed text; without a title, the turn ends with the packaged skip
    notice (``utter_set_memory_button_skipped``). Those paths do not set the
    written key.

    A valid ``set:`` payload must appear on the latest agent message's buttons;
    otherwise the write is skipped as stale. Schema writability alone is not
    enough — forged channel text must not write closed-list or project fields.
    Missing fields and values that fail coerce are also skipped as stale so the
    user gets a notice instead of a silently dropped message.

    Memory validation tools (``run_after_setting_<entry>``) run on successful
    writes (same path as ``set_fields``). A rejecting tool rolls the write back;
    collect does not advance. The LLM may still respond using the button title
    when the channel supplies ``button_title``; the raw ``set:`` payload stays
    out of the prompt. A memory write denied by the access contract (for
    example a second tap on a write-once project field) ends with the packaged
    notice instead of invoking the LLM.

    Args:
        tracker_handle: Live tracker handle for the turn.
        turn: Incoming user turn as converted from the channel message.
        skill_catalog: Loaded skill catalog (schemas and access contracts).
        project_memory: Project ``memory.yml`` schema.
        tool_funcs: Skill-scoped tool registry for memory validation tools.
        call_tool_func: In-process tool invoker (``SkillExecutor.call_tool_func``).

    Returns:
        The turn to pass to
        :meth:`~rasa.mantle.orchestration.orchestrator.Orchestrator.run_turn`.
    """
    classification = classify_inbound_button_payload(turn.text)
    if classification.kind == InboundButtonPayloadKind.TEXT:
        return turn
    if classification.kind == InboundButtonPayloadKind.INVALID_SET_MEMORY:
        return _turn_for_invalid_set_memory(turn)

    parsed = classification.parsed
    if parsed is None:
        return turn.model_copy(update={"suppress_llm_user_message": True})

    plan = _plan_set_memory_button_write(
        turn,
        parsed,
        tracker_handle=tracker_handle,
        skill_catalog=skill_catalog,
        project_memory=project_memory,
    )
    if isinstance(plan, IncomingTurn):
        return plan
    return await _dispatch_set_memory_button_write(
        turn,
        parsed,
        plan,
        tracker_handle=tracker_handle,
        tool_funcs=tool_funcs,
        call_tool_func=call_tool_func,
    )
